//! A SkyFrame template found among the interleaved axes of two SkyFrames,
//! checked against the C library.
//!
//! `sky_interleave_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_interleave_probe.c`. SkyFrame Match takes the
//! first target axis that belongs to a SkyFrame, then searches the remaining
//! axes for the other axis of that same SkyFrame, passing over the axes of
//! any other (skyframe.c `Match`).

#[path = "sky_interleave_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::frames::FrameSearch;
use starlink_ast::frames::{CmpFrame, Frame, FrameRef, SkyFrame, SkySystem};

fn sky(system: SkySystem) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    f.set_system(system);
    f
}

fn found(perm: [usize; 4]) -> Option<[f64; 2]> {
    let mut target = CmpFrame::new(
        Box::new(sky(SkySystem::Fk5)),
        Box::new(sky(SkySystem::Galactic)),
    );
    target.perm_axes(&perm).unwrap();
    let mut template = sky(SkySystem::Fk5);
    template.set_max_axes(4).unwrap();
    let fs = target.find_frame_template(&template, "").unwrap()?;
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let columns: Vec<[f64; 1]> = cases::POINT.iter().map(|&v| [v]).collect();
    let columns: Vec<&[f64]> = columns.iter().map(|c| &c[..]).collect();
    let out = map
        .transform(&PointSet::from_columns(&columns).unwrap(), true)
        .unwrap();
    let p = out.point(0);
    Some([p[0], p[1]])
}

#[test]
fn interleaved_sky_axes_match_the_c_library() {
    let failures: Vec<String> = cases::CASES
        .iter()
        .filter_map(|&(perm, want)| {
            let got = found(perm);
            (got != want).then(|| format!("{perm:?}: got {got:?}, C gives {want:?}"))
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
